
import React, { useContext } from 'react';
import { Routes, Route } from 'react-router-dom';
import { ThemeProvider as MuiThemeProvider, CssBaseline } from '@mui/material';
import { Global, css } from '@emotion/react';
import Lobby from './pages/Lobby';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import ChatPage from './pages/ChatPage';
import GamePage from './pages/GamePage';
import SelectionPage from './pages/SelectionPage';
import RankingPage from './pages/RankingPage';
import { AppContext } from './contexts/AppContext';
import { getTheme, ThemeName } from './theme';
import './App.css';

const GlobalStyle = ({ themeName }: { themeName: ThemeName }) => (
  <Global
    styles={css`
      body {
        background-image: ${themeName === 'sea' 
          ? `url('https://images.unsplash.com/photo-1509477539974-73c07273c79c?q=80&w=2070&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D')` 
          : themeName === 'space' 
          ? `url('https://images.unsplash.com/photo-1534796636912-3b95b3ab5986?q=80&w=2071&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D')` 
          : 'none'};
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
        transition: background-image 0.5s ease-in-out;
      }
    `}
  />
);

function App() {
  const appContext = useContext(AppContext);

  if (!appContext) {
    return null; // Or a loading spinner
  }

  const { theme: themeName } = appContext;
  const muiTheme = getTheme(themeName);

  return (
    <MuiThemeProvider theme={muiTheme}>
      <CssBaseline />
      <GlobalStyle themeName={themeName} />
      <Routes>
        <Route path="/" element={<Lobby />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
        <Route path="/chat" element={<ChatPage />} />
        <Route path="/game" element={<GamePage />} />
        <Route path="/select" element={<SelectionPage />} />
        <Route path="/ranking" element={<RankingPage />} />
      </Routes>
    </MuiThemeProvider>
  );
}

export default App;
