import { createTheme } from '@mui/material/styles';

// 테마 이름을 위한 타입 정의
export type ThemeName = 'default' | 'sea' | 'space';

// 기본 테마
export const defaultTheme = createTheme({
  palette: {
    mode: 'light',
    primary: {
      main: '#6C63FF',
    },
    secondary: {
      main: '#FF6584',
    },
    background: {
      default: '#F4F6F8',
      paper: '#FFFFFF',
    },
    text: {
      primary: '#333333',
    },
  },
  typography: {
    fontFamily: ['Poppins', 'sans-serif'].join(','),
    h4: { fontWeight: 700 },
    h5: { fontWeight: 600 },
  },
});

// 바다 테마
export const seaTheme = createTheme({
  palette: {
    mode: 'light',
    primary: {
      main: '#0077be', // Deep sea blue
    },
    secondary: {
      main: '#89cff0', // Baby blue
    },
    background: {
      default: '#f0f8ff', // Alice blue
      paper: '#ffffff',
    },
    text: {
      primary: '#003d5b',
    },
  },
  typography: {
    fontFamily: ['Poppins', 'sans-serif'].join(','),
    h4: { fontWeight: 700 },
    h5: { fontWeight: 600 },
  },
});

// 우주 테마
export const spaceTheme = createTheme({
  palette: {
    mode: 'dark',
    primary: {
      main: '#9d72ff', // Light purple
    },
    secondary: {
      main: '#f7aef8', // Light pink
    },
    background: {
      default: '#1a1a2e', // Dark blue
      paper: '#2c2c54',
    },
    text: {
      primary: '#ffffff',
      secondary: '#b2b2b2',
    },
  },
  typography: {
    fontFamily: ['Poppins', 'sans-serif'].join(','),
    h4: { fontWeight: 700 },
    h5: { fontWeight: 600 },
  },
});

// 테마 이름에 따라 적절한 테마 객체를 반환하는 함수
export const getTheme = (themeName: ThemeName) => {
  switch (themeName) {
    case 'sea':
      return seaTheme;
    case 'space':
      return spaceTheme;
    default:
      return defaultTheme;
  }
};